window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0799ccb8c6be33a3"]={"versions": [{"id": "FIG-0799ccb8c6be33a3", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Teilablaufs „Read Length“ innerhalb der Prüffunktion <code>E2E_P04Check()</code> des AUTOSAR E2E-Profils 4 (AUTOSAR_PRS_E2EProtocol). Das Diagramm detailliert einen Teilschritt der Datenprüfung im Rahmen des End-to-End-Schutzes sicherheitsrelevanter Kommunikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontext:</strong> <code>E2E_P04Check()</code> (gekennzeichnet über ein Subaktivitäts-/Aufruf-Symbol oben links).\n</li><li><strong>Eingangsdaten / Puffer:</strong> Byte-Array <code>Data[]</code> mit dem Offset-Parameter <code>Offset</code>.\n</li><li><strong>Lokale Variable:</strong> <code>ReceivedLength</code> vom Datentyp <code>uint16</code>.\n</li><li><strong>Aktion:</strong> <code>Copy bytes Data[Offset...Offset+1] in Big Endian order to uint16 local variable ReceivedLength</code>.\n</li><li><strong>Kommentar / Note:</strong> Über eine gestrichelte Linie mit der Aktion verknüpfte Notiz: „Options is always at the same location.“.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Kontrollfluss beginnt am Startknoten (Initial Node).\n</li><li>Übergang zur einzigen Verarbeitungsaktion: Aus dem Byte-Array <code>Data</code> werden zwei aufeinanderfolgende Bytes an der Position <code>Offset</code> bis <code>Offset + 1</code> in Big-Endian-Byte-Reihenfolge extrahiert und in die lokale Variable <code>ReceivedLength</code> (<code>uint16</code>) geschrieben.\n</li><li>Nach Abschluss der Zuweisung wird der Kontrollfluss direkt zum Endknoten (Activity Final Node) weitergeleitet.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Gemäß <code>[PRS_E2E_00357]</code> verhält sich der Teilschritt „Read Length“ exakt wie im Aktivitätsdiagramm definiert.\n</li><li>Implementierer müssen beachten, dass das Längenfeld im Datenstrom fest in Big-Endian-Reihenfolge (Most Significant Byte zuerst) kodiert ist und portabel auf Host-Architekturen beliebiger Endianness in eine 16-Bit-Ganzzahl (<code>uint16</code>) eingelesen werden muss.\n</li><li>Das Vorhandensein ausreichender Puffergröße (mindestens <code>Offset + 2</code> Bytes) muss vorab bzw. in den übergeordneten Eingangsprüfungen von <code>E2E_P04Check()</code> validiert sein, um Speicherzugriffsverletzungen zu vermeiden.\n</li></ul>"}, {"id": "FIG-813aa695c3ddb3f4", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Teilablaufs „Read Length“ innerhalb der Prüffunktion <code>E2E_P04Check()</code> des AUTOSAR E2E-Profils 4 (AUTOSAR_PRS_E2EProtocol). Das Diagramm detailliert einen Teilschritt der Datenprüfung im Rahmen des End-to-End-Schutzes sicherheitsrelevanter Kommunikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontext:</strong> <code>E2E_P04Check()</code> (gekennzeichnet über ein Subaktivitäts-/Aufruf-Symbol oben links).\n</li><li><strong>Eingangsdaten / Puffer:</strong> Byte-Array <code>Data[]</code> mit dem Offset-Parameter <code>Offset</code>.\n</li><li><strong>Lokale Variable:</strong> <code>ReceivedLength</code> vom Datentyp <code>uint16</code>.\n</li><li><strong>Aktion:</strong> <code>Copy bytes Data[Offset...Offset+1] in Big Endian order to uint16 local variable ReceivedLength</code>.\n</li><li><strong>Kommentar / Note:</strong> Über eine gestrichelte Linie mit der Aktion verknüpfte Notiz: „Options is always at the same location.“.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Kontrollfluss beginnt am Startknoten (Initial Node).\n</li><li>Übergang zur einzigen Verarbeitungsaktion: Aus dem Byte-Array <code>Data</code> werden zwei aufeinanderfolgende Bytes an der Position <code>Offset</code> bis <code>Offset + 1</code> in Big-Endian-Byte-Reihenfolge extrahiert und in die lokale Variable <code>ReceivedLength</code> (<code>uint16</code>) geschrieben.\n</li><li>Nach Abschluss der Zuweisung wird der Kontrollfluss direkt zum Endknoten (Activity Final Node) weitergeleitet.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Gemäß <code>[PRS_E2E_00357]</code> verhält sich der Teilschritt „Read Length“ exakt wie im Aktivitätsdiagramm definiert.\n</li><li>Implementierer müssen beachten, dass das Längenfeld im Datenstrom fest in Big-Endian-Reihenfolge (Most Significant Byte zuerst) kodiert ist und portabel auf Host-Architekturen beliebiger Endianness in eine 16-Bit-Ganzzahl (<code>uint16</code>) eingelesen werden muss.\n</li><li>Das Vorhandensein ausreichender Puffergröße (mindestens <code>Offset + 2</code> Bytes) muss vorab bzw. in den übergeordneten Eingangsprüfungen von <code>E2E_P04Check()</code> validiert sein, um Speicherzugriffsverletzungen zu vermeiden.\n</li></ul>"}, {"id": "FIG-1ba9b3585a48edad", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des E2E-Prüfschritts „Read Length“ innerhalb des Profilprüfalgorithmus <code>E2E_P44Check()</code> der AUTOSAR E2E-Bibliothek (End-to-End Communication Protection). Das Diagramm modelliert einen atomaren Teilablauf der Datenstromprüfung auf Empfängerseite vor weiteren Plausibilitäts- und Integritätschecks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Kontext/Aktion: Aufrufkontext ist die Prüffunktion <code>E2E_P44Check()</code>.\n</li><li>Eingangsdaten: Byte-Array <code>Data[]</code> (serialisierte Nutz- und Protokolldaten) sowie die Konfigurations- oder Positionsvariable <code>Offset</code>.\n</li><li>Lokale Variablen / Entitäten: <code>ReceivedLength</code> vom Datentyp <code>uint16</code>.\n</li><li>Kommentar/Notiz: Assoziierter Kommentar <code>Options is always at the same location.</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ausgehend vom Initialknoten geht der Kontrollfluss in die Verarbeitungsaktion über.\n</li><li>In der Aktion werden zwei aufeinanderfolgende Bytes <code>Data[Offset...Offset+1]</code> aus dem Eingangs-Array in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in die lokale 16-Bit-Variable <code>ReceivedLength</code> kopiert.\n</li><li>Nach Abschluss des Lesevorgangs erreicht der Kontrollfluss direkt den Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Rekonstruktion der übertragenen Datenlänge aus zwei Bytes im Big-Endian-Format ist für E2E-Profile mit dynamischer oder geprüfter Datenlänge (hier Profil 44) normativ vorgeschrieben. Implementierer müssen sicherstellen, dass <code>Offset</code> und <code>Offset + 1</code> innerhalb der gültigen Grenzen des Puffers <code>Data</code> liegen, um Speicherzugriffsfehler (Out-of-bounds Read) zu vermeiden, und dass das Auslesen unabhängig von der Endianness der Host-CPU strikt in Big-Endian erfolgt.</p>"}, {"id": "FIG-21e0da9c3e754e87", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des E2E-Prüfschritts „Read Length“ innerhalb des Profilprüfalgorithmus <code>E2E_P04Check()</code> der AUTOSAR E2E-Bibliothek (End-to-End Communication Protection). Das Diagramm modelliert einen atomaren Teilablauf der Datenstromprüfung auf Empfängerseite vor weiteren Plausibilitäts- und Integritätschecks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Kontext/Aktion: Aufrufkontext ist die Prüffunktion <code>E2E_P04Check()</code>.\n</li><li>Eingangsdaten: Byte-Array <code>Data[]</code> (serialisierte Nutz- und Protokolldaten) sowie die Konfigurations- oder Positionsvariable <code>Offset</code>.\n</li><li>Lokale Variablen / Entitäten: <code>ReceivedLength</code> vom Datentyp <code>uint16</code>.\n</li><li>Kommentar/Notiz: Assoziierter Kommentar <code>Options is always at the same location.</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ausgehend vom Initialknoten geht der Kontrollfluss in die Verarbeitungsaktion über.\n</li><li>In der Aktion werden zwei aufeinanderfolgende Bytes <code>Data[Offset...Offset+1]</code> aus dem Eingangs-Array in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in die lokale 16-Bit-Variable <code>ReceivedLength</code> kopiert.\n</li><li>Nach Abschluss des Lesevorgangs erreicht der Kontrollfluss direkt den Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Rekonstruktion der übertragenen Datenlänge aus zwei Bytes im Big-Endian-Format ist für E2E-Profile mit dynamischer oder geprüfter Datenlänge (hier Profil 4) normativ vorgeschrieben. Implementierer müssen sicherstellen, dass <code>Offset</code> und <code>Offset + 1</code> innerhalb der gültigen Grenzen des Puffers <code>Data</code> liegen, um Speicherzugriffsfehler (Out-of-bounds Read) zu vermeiden, und dass das Auslesen unabhängig von der Endianness der Host-CPU strikt in Big-Endian erfolgt.</p>"}], "trans": [{"from": "FIG-0799ccb8c6be33a3", "to": "FIG-813aa695c3ddb3f4", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
